package studio.manga.documents;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="document") public class Document { @Id public UUID id=UUID.randomUUID(); @Column(name="project_id",nullable=false) public UUID projectId; @Column(name="chapter_id") public UUID chapterId; @Column(nullable=false) public String title; @Column(nullable=false) public String type; @Column(nullable=false) public String content=""; @Column(nullable=false) public int revision=1; @Column(name="created_at",nullable=false) public Instant createdAt=Instant.now(); @Column(name="updated_at",nullable=false) public Instant updatedAt=Instant.now(); protected Document(){} public Document(UUID projectId,UUID chapterId,String title,String type){this.projectId=projectId;this.chapterId=chapterId;this.title=title;this.type=type;} }
